//! Shared-convention goldens (spec S13): every `conv_*` key of the Python
//! golden JSON, checked against this crate.
//!
//! The constants come from `tests/golden/mod.rs`, generated by
//! `tools/gen_golden_rs.py` (`--check` proves it matches the JSON). The key
//! names are identical in the equity and FX JSONs.
//!
//! Tolerances. VaR/ES are an order statistic and a short sum of 2-dp
//! numbers: both sides sum the same values in the same (descending) order,
//! so they agree to a few ulps; 1e-12 relative is ~4500 ulps of slack. The
//! Basel CDF is a pmf recursion of at most ~16 terms, each a product of
//! exact ratios: 1e-13 absolute is ~450 ulps at 1.0. Kupiec LR is a
//! difference of log-likelihoods of size ~25, so 1e-12 absolute (~3500
//! ulps of the operands) covers the cancellation. Higham is iterated to a
//! 1e-12 relative step on both sides, so 1e-8 absolute (spec) is loose;
//! clipping is one eigen-decomposition, 1e-12 relative (spec). EWMA is a
//! 250-step recursion with contraction 0.94: 1e-14 relative.
#![allow(clippy::needless_range_loop)]

mod golden;

use fx_var_engine::backtest::*;
use fx_var_engine::expected_shortfall::empirical_var_es;
use fx_var_engine::matrix::Matrix;
use fx_var_engine::parametric::cornish_fisher_valid;
use fx_var_engine::psd::{cholesky_repair, PsdRepair};
use fx_var_engine::returns::{ewma_volatility, ReturnsMatrix};

/// `P_i = round2(1000 sin(0.37 i + 0.1) (1 + 0.5 cos(0.11 i)))`,
/// `round2(x) = floor(100 x + 0.5) / 100`, i = 0..249.
fn sample_p() -> Vec<f64> {
    (0..250)
        .map(|i| {
            let x = 1000.0 * (0.37 * i as f64 + 0.1).sin() * (1.0 + 0.5 * (0.11 * i as f64).cos());
            (x * 100.0 + 0.5).floor() / 100.0
        })
        .collect()
}

fn rel(a: f64, b: f64, tol: f64) {
    assert!((a - b).abs() <= tol * b.abs().max(1e-300), "{a} vs {b} (rel tol {tol})");
}

#[test]
fn conv_var_es() {
    let p = sample_p();
    for (a, v, e) in [
        (0.010, golden::CONV_VAR_A010, golden::CONV_ES_A010),
        (0.025, golden::CONV_VAR_A025, golden::CONV_ES_A025),
        (0.050, golden::CONV_VAR_A050, golden::CONV_ES_A050),
    ] {
        let (var, es) = empirical_var_es(&p, a, None).unwrap();
        rel(var, v, 1e-12);
        rel(es, e, 1e-12);
    }
}

#[test]
fn conv_basel() {
    use golden::*;
    let cases = [
        (250, 4, 0.01, CONV_BASEL_ZONE_N250_X4_A010, CONV_BASEL_K_N250_X4_A010, CONV_BASEL_CDF_N250_X4_A010),
        (250, 5, 0.01, CONV_BASEL_ZONE_N250_X5_A010, CONV_BASEL_K_N250_X5_A010, CONV_BASEL_CDF_N250_X5_A010),
        (250, 9, 0.01, CONV_BASEL_ZONE_N250_X9_A010, CONV_BASEL_K_N250_X9_A010, CONV_BASEL_CDF_N250_X9_A010),
        (250, 10, 0.01, CONV_BASEL_ZONE_N250_X10_A010, CONV_BASEL_K_N250_X10_A010, CONV_BASEL_CDF_N250_X10_A010),
        (500, 8, 0.01, CONV_BASEL_ZONE_N500_X8_A010, CONV_BASEL_K_N500_X8_A010, CONV_BASEL_CDF_N500_X8_A010),
        (500, 9, 0.01, CONV_BASEL_ZONE_N500_X9_A010, CONV_BASEL_K_N500_X9_A010, CONV_BASEL_CDF_N500_X9_A010),
        (500, 12, 0.01, CONV_BASEL_ZONE_N500_X12_A010, CONV_BASEL_K_N500_X12_A010, CONV_BASEL_CDF_N500_X12_A010),
        (1000, 15, 0.01, CONV_BASEL_ZONE_N1000_X15_A010, CONV_BASEL_K_N1000_X15_A010, CONV_BASEL_CDF_N1000_X15_A010),
        (250, 12, 0.025, CONV_BASEL_ZONE_N250_X12_A025, CONV_BASEL_K_N250_X12_A025, CONV_BASEL_CDF_N250_X12_A025),
    ];
    for (n, x, a, zone, k, cdf) in cases {
        let r = basel_traffic_light(&BaselInput { n_obs: n, n_exceptions: x, alpha: a }).unwrap();
        let z = match r.zone {
            Zone::Green => 0.0,
            Zone::Yellow => 1.0,
            Zone::Red => 2.0,
        };
        assert_eq!(z, zone, "zone n={n} x={x} a={a}");
        assert!((r.multiplier - k).abs() < 1e-15, "k n={n} x={x}: {} vs {k}", r.multiplier);
        assert!((r.cumulative_prob - cdf).abs() < 1e-13, "cdf n={n} x={x}: {} vs {cdf}", r.cumulative_prob);
    }
}

#[test]
fn conv_kupiec() {
    for (n, x, want) in [
        (250, 5, golden::CONV_KUPIEC_LR_N250_X5),
        (500, 9, golden::CONV_KUPIEC_LR_N500_X9),
        (250, 0, golden::CONV_KUPIEC_LR_N250_X0),
    ] {
        let r = kupiec_pof(&KupiecInput { n_obs: n, n_exceptions: x, alpha: 0.01 }).unwrap();
        assert!((r.lr - want).abs() < 1e-12, "n={n} x={x}: {} vs {want}", r.lr);
    }
}

#[test]
fn conv_acerbi_szekely() {
    let z2 = acerbi_szekely_z2(&sample_p(), &[1500.0], &[1800.0], 0.025).unwrap();
    assert!((z2 - golden::CONV_AS_Z2).abs() < 1e-12, "{z2}");
}

#[test]
fn conv_cornish_fisher() {
    let f = |s, k, a| if cornish_fisher_valid(s, k, a).unwrap() { 1.0 } else { 0.0 };
    assert_eq!(f(0.122, -0.427, 0.01), golden::CONV_CF_VALID_S0122_KM0427);
    assert_eq!(f(0.0, 0.0, 0.01), golden::CONV_CF_VALID_S00_K00);
    assert_eq!(f(1.0, 1.0, 0.01), golden::CONV_CF_VALID_S10_K10);
    assert_eq!(f(-0.0105, 8.0001, 0.01), golden::CONV_CF_VALID_SM0105_K80001);
    assert_eq!(f(0.122, -0.427, 0.001), golden::CONV_CF_VALID_A001_S0122_KM0427);
}

fn bad3() -> Matrix {
    Matrix::from_rows(&[vec![1.0, 0.9, 0.9], vec![0.9, 1.0, -0.9], vec![0.9, -0.9, 1.0]]).unwrap()
}

#[test]
fn conv_cholesky_repairs() {
    let a = bad3();
    assert!(cholesky_repair(&a, PsdRepair::None).is_err());
    let h = cholesky_repair(&a, PsdRepair::Higham).unwrap().repaired.unwrap();
    for ((i, j), want) in [((0, 1), golden::CONV_HIGHAM_A01), ((0, 2), golden::CONV_HIGHAM_A02), ((1, 2), golden::CONV_HIGHAM_A12)] {
        assert!((h.get(i, j) - want).abs() < golden::TOL_CONV_HIGHAM_ABS, "higham ({i},{j}): {} vs {want}", h.get(i, j));
    }
    let c = cholesky_repair(&a, PsdRepair::Clip).unwrap().repaired.unwrap();
    for ((i, j), want) in [((0, 1), golden::CONV_CLIP_A01), ((0, 2), golden::CONV_CLIP_A02), ((1, 2), golden::CONV_CLIP_A12)] {
        rel(c.get(i, j), want, golden::TOL_CONV_CLIP_REL);
    }
}

#[test]
fn conv_ewma() {
    let p = sample_p();
    let mut d = Matrix::zeros(p.len(), 1);
    for (i, v) in p.iter().enumerate() {
        d.set(i, 0, v / 1e5);
    }
    let r = ReturnsMatrix::new(vec!["FX:EUR".to_string()], d).unwrap();
    let ev = ewma_volatility(&r, 0.94).unwrap();
    rel(ev.sigma_next[0], golden::CONV_EWMA_SIGMA_LAST, 1e-14);
}
